using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        ref float ptr = ref MemoryMarshal.GetReference(values);
        int length = values.Length;
        int i = 0;

        if (Vector512.IsHardwareAccelerated && length >= Vector512<float>.Count)
        {
            var acc = Vector512<float>.One;
            int lastBlock = length - Vector512<float>.Count;
            for (; i <= lastBlock; i += Vector512<float>.Count)
                acc *= Vector512.LoadUnsafe(ref ptr, (nuint)i);

            // Reduce 512 -> scalar
            var lo = acc.GetLower();
            var hi = acc.GetUpper();
            lo *= hi;
            var lo128 = lo.GetLower();
            var hi128 = lo.GetUpper();
            lo128 *= hi128;
            float product = lo128[0] * lo128[1] * lo128[2] * lo128[3];
            for (; i < length; i++)
                product *= Unsafe.Add(ref ptr, i);
            return product;
        }

        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count)
        {
            var acc = Vector256<float>.One;
            int lastBlock = length - Vector256<float>.Count;
            for (; i <= lastBlock; i += Vector256<float>.Count)
                acc *= Vector256.LoadUnsafe(ref ptr, (nuint)i);

            // Reduce 256 -> scalar
            var lo = acc.GetLower();
            var hi = acc.GetUpper();
            lo *= hi;
            float product = lo[0] * lo[1] * lo[2] * lo[3];
            for (; i < length; i++)
                product *= Unsafe.Add(ref ptr, i);
            return product;
        }

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count)
        {
            var acc = Vector128<float>.One;
            int lastBlock = length - Vector128<float>.Count;
            for (; i <= lastBlock; i += Vector128<float>.Count)
                acc *= Vector128.LoadUnsafe(ref ptr, (nuint)i);

            float product = acc[0] * acc[1] * acc[2] * acc[3];
            for (; i < length; i++)
                product *= Unsafe.Add(ref ptr, i);
            return product;
        }

        // Scalar fallback
        float result = 1f;
        for (; i < length; i++)
            result *= Unsafe.Add(ref ptr, i);
        return result;
    }
}

